head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > customLabelFormatter]<br/>선택된 아이템들의 라벨 표시값을 동적으로 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "useLocale, useItemLocale 속성으로 각 아이템에 다국어가 적용되면 사용자 정의 함수의 파라미터에 다국어가 전달됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {     
        useLocale : true,
        useItemLocale : true,
        customLabelFormatter : "scwin.fn_customlabelformatter",
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    strTarget += '<xf:checkcombobox ' + strNameSpace + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_Item">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:checkcombobox>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "checkcombobox",
        strTarget,
        grp_comp
    );
}



scwin.btn_getText_onclick = function (e) {
    let rtn = '';
    rtn = target1.render.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("selectbox 의 label : " + rtn);    
};



scwin.fn_customlabelformatter = function(selectData, isOpen) {    
    let data = [];
    for(var i=0;i < selectData.length;i++){        
        data.push(selectData[i].label);        
    }

    data.push(" isOpen : "+isOpen);    

    return data;
}
